function update(e){let c=document.querySelector("#fast").checked,r=document.querySelector("#cheap").checked,t=document.querySelector("#good").checked,d=e.srcElement.id;if("fast"==d){if(c&&r)return document.querySelector("#good").checked=!1;if(c&&t)return document.querySelector("#cheap").checked=!1}if("cheap"==d){if(r&&t)return document.querySelector("#fast").checked=!1;if(r&&c)return document.querySelector("#good").checked=!1}if("good"==d){if(t&&c)return document.querySelector("#cheap").checked=!1;if(t&&r)return document.querySelector("#fast").checked=!1}}document.querySelector("#fast").addEventListener("change",update),document.querySelector("#cheap").addEventListener("change",update),document.querySelector("#good").addEventListener("change",update);